from math import gcd
from itertools import combinations

EXPECT = {2: 2, 3: 2, 4: 3, 5: 3, 6: 3, 7: 3, 8: 4}
WITNESSES = {
    2: [1, 2], 3: [1, 2], 4: [1, 2, 4], 5: [1, 2, 4],
    6: [1, 2, 4], 7: [1, 2, 4], 8: [3, 4, 6, 8],
}

def triple_bad(t):
    g = gcd(gcd(t[0], t[1]), t[2])
    a, b, c = t[0] // g, t[1] // g, t[2] // g
    return a == b or a == c or b == c

def valid(S):
    # every 3-subset of S must have NOT-all-equal pairwise gcds
    return not any(
        all(gcd(x, y) == g0 for (x, y) in pairs)
        for T in combinations(S, 3)
        for g0 in [gcd(gcd(T[0], T[1]), T[2])]
        for pairs in [list(combinations(T, 2))]
    )

def f3(N):
    best = 0
    for mask in range(1 << N):
        S = [i + 1 for i in range(N) if (mask >> i) & 1]
        if valid(S) and len(S) > best:
            best = len(S)
    return best

def verify():
    for N in range(2, 9):
        if f3(N) != EXPECT[N]:
            raise SystemExit(1)
        S = WITNESSES[N]
        if len(S) != EXPECT[N] or not valid(S):
            raise SystemExit(1)
        for extra in combinations(range(1, N + 1), EXPECT[N] + 1):
            if valid(list(extra)):
                raise SystemExit(1)
    raise SystemExit(0)

verify()
